INSERT INTO exercises (area, level, topic, exercise_type, exam_format, title_de, title_en, instructions_de, instructions_en, content, solution, explanation_de, explanation_en, difficulty, sort_order)
VALUES ('sprachbausteine', 'c1', 'sprachbausteine', 'sprachbausteine', 'telc', 'Digitalisierung im Gesundheitswesen', 'Digitalization in Healthcare', 'Lesen Sie den Text und wählen Sie für jede Lücke die richtige Lösung.', 'Read the text and choose the correct option for each gap.', '{"text": "Die Digitalisierung hat __(1)__ den letzten Jahren auch das Gesundheitswesen grundlegend verändert. Elektronische Patientenakten ermöglichen es Ärzten, __(2)__ einen schnellen Überblick über die Krankengeschichte zu verschaffen. __(3)__ die anfängliche Skepsis vieler Mediziner ist die Akzeptanz digitaler Lösungen __(4)__ gestiegen. Besonders in ländlichen Gebieten, __(5)__ es an Fachärzten mangelt, bietet die Telemedizin neue Möglichkeiten der Versorgung. Kritiker __(6)__ jedoch ein, dass der Datenschutz nicht ausreichend gewährleistet sei. Es __(7)__ sich daher die Frage, inwieweit persönliche Gesundheitsdaten vor unbefugtem Zugriff geschützt werden können. __(8)__ dieser Bedenken überwiegen nach Ansicht vieler Experten die Vorteile der Digitalisierung.", "gaps": [{"options": ["in", "seit", "vor", "während"]}, {"options": ["sich", "ihnen", "denen", "einem"]}, {"options": ["Trotz", "Wegen", "Aufgrund", "Angesichts"]}, {"options": ["deutlich", "insbesondere", "allerdings", "vielmehr"]}, {"options": ["wo", "dass", "weil", "wenn"]}, {"options": ["wenden", "stellen", "setzen", "bringen"]}, {"options": ["stellt", "gibt", "lässt", "macht"]}, {"options": ["Ungeachtet", "Infolge", "Anstatt", "Zugunsten"]}]}', '{"answers": ["in", "sich", "Trotz", "deutlich", "wo", "wenden", "stellt", "Ungeachtet"]}', 'Typische Sprachbausteine: Präpositionen (in + Dativ), Reflexivpronomen, Konzessivpräpositionen, Relativadverbien, Funktionsverbgefüge.', 'Typical language building blocks: prepositions (in + dative), reflexive pronouns, concessive prepositions, relative adverbs, function verb constructions.', 3, 500);

INSERT INTO exercises (area, level, topic, exercise_type, exam_format, title_de, title_en, instructions_de, instructions_en, content, solution, explanation_de, explanation_en, difficulty, sort_order)
VALUES ('sprachbausteine', 'c1', 'sprachbausteine', 'sprachbausteine', 'telc', 'Die Vier-Tage-Woche', 'The Four-Day Work Week', 'Lesen Sie den Text und wählen Sie für jede Lücke die richtige Lösung.', 'Read the text and choose the correct option for each gap.', '{"text": "Die Diskussion __(1)__ die Einführung einer Vier-Tage-Woche hat in den vergangenen Monaten an Dynamik gewonnen. Befürworter __(2)__ darauf hin, dass kürzere Arbeitszeiten die Produktivität steigern könnten. __(3)__ zeigen Studien aus Skandinavien, dass Mitarbeiter bei reduzierter Arbeitszeit motivierter und seltener krank sind. __(4)__ ist zu berücksichtigen, dass nicht alle Branchen gleichermaßen von diesem Modell profitieren würden. Im Gesundheitswesen etwa __(5)__ eine Umsetzung auf erhebliche Schwierigkeiten stoßen. Die Gewerkschaften __(6)__ Stellung für eine Arbeitszeitverkürzung bei vollem Lohnausgleich. Arbeitgeberverbände hingegen __(7)__ vor den wirtschaftlichen Folgen. Es bleibt __(8)__, ob sich ein Kompromiss finden lässt.", "gaps": [{"options": ["um", "über", "für", "auf"]}, {"options": ["weisen", "zeigen", "deuten", "stellen"]}, {"options": ["Tatsächlich", "Obwohl", "Trotzdem", "Hingegen"]}, {"options": ["Allerdings", "Deshalb", "Folglich", "Außerdem"]}, {"options": ["würde", "könnte", "sollte", "dürfte"]}, {"options": ["nehmen", "beziehen", "ergreifen", "treten"]}, {"options": ["warnen", "drohen", "fürchten", "mahnen"]}, {"options": ["abzuwarten", "festzustellen", "anzumerken", "herauszufinden"]}]}', '{"answers": ["um", "weisen", "Tatsächlich", "Allerdings", "würde", "nehmen", "warnen", "abzuwarten"]}', 'Schwerpunkte: Präpositionen mit Verben (Diskussion um), Funktionsverbgefüge (Stellung nehmen), Konjunktiv II, Konnektoren.', 'Focus: verb-preposition collocations (Diskussion um), function verbs (Stellung nehmen), subjunctive II, connectors.', 3, 501);

INSERT INTO exercises (area, level, topic, exercise_type, exam_format, title_de, title_en, instructions_de, instructions_en, content, solution, explanation_de, explanation_en, difficulty, sort_order)
VALUES ('sprachbausteine', 'c1', 'sprachbausteine', 'sprachbausteine', 'telc', 'Nachhaltiger Konsum', 'Sustainable Consumption', 'Lesen Sie den Text und wählen Sie für jede Lücke die richtige Lösung.', 'Read the text and choose the correct option for each gap.', '{"text": "Nachhaltiger Konsum ist längst kein Nischenthema mehr, __(1)__ ein gesamtgesellschaftliches Anliegen. Immer mehr Verbraucher legen Wert __(2)__ fair produzierte und umweltfreundliche Produkte. __(3)__ stellt sich die Frage, ob individuelles Konsumverhalten tatsächlich einen messbaren Beitrag zum Klimaschutz leisten kann. Wissenschaftler __(4)__ zu dem Schluss, dass systemische Veränderungen notwendig sind. __(5)__ der Einzelne allein die Umweltkrise nicht lösen kann, hat bewusster Konsum durchaus eine Signalwirkung. Unternehmen reagieren zunehmend __(6)__ die veränderte Nachfrage und passen ihre Produktionsweise an. __(7)__ bleibt die Frage, inwieweit Greenwashing von echtem Engagement zu unterscheiden ist. Letztlich __(8)__ es an der Politik, verbindliche Rahmenbedingungen zu schaffen.", "gaps": [{"options": ["sondern", "aber", "jedoch", "dennoch"]}, {"options": ["auf", "für", "an", "über"]}, {"options": ["Dennoch", "Deshalb", "Obwohl", "Schließlich"]}, {"options": ["kommen", "gelangen", "führen", "geraten"]}, {"options": ["Wenngleich", "Weil", "Sofern", "Damit"]}, {"options": ["auf", "an", "über", "für"]}, {"options": ["Gleichwohl", "Infolgedessen", "Demzufolge", "Dafür"]}, {"options": ["liegt", "steht", "geht", "kommt"]}]}', '{"answers": ["sondern", "auf", "Dennoch", "kommen", "Wenngleich", "auf", "Gleichwohl", "liegt"]}', 'Schwerpunkte: nicht...sondern, Wert legen auf, zu dem Schluss kommen, Konzessivkonjunktionen (wenngleich), reagieren auf.', 'Focus: nicht...sondern, Wert legen auf, zu dem Schluss kommen, concessive conjunctions (wenngleich), reagieren auf.', 3, 502);

INSERT INTO exercises (area, level, topic, exercise_type, exam_format, title_de, title_en, instructions_de, instructions_en, content, solution, explanation_de, explanation_en, difficulty, sort_order)
VALUES ('sprachbausteine', 'c1', 'sprachbausteine', 'sprachbausteine', 'telc', 'Künstliche Intelligenz in der Arbeitswelt', 'Artificial Intelligence in the Workplace', 'Lesen Sie den Text und wählen Sie für jede Lücke die richtige Lösung.', 'Read the text and choose the correct option for each gap.', '{"text": "Der Einsatz künstlicher Intelligenz __(1)__ in nahezu allen Wirtschaftsbereichen an Bedeutung. Viele Arbeitnehmer fürchten sich __(2)__ dem Verlust ihres Arbeitsplatzes. Diese Sorge ist nicht __(3)__ der Hand zu weisen, denn Studien prognostizieren, dass zahlreiche Routinetätigkeiten automatisiert werden. __(4)__ entstehen gleichzeitig neue Berufsfelder, die bislang undenkbar waren. Entscheidend wird sein, __(5)__ es gelingt, die Beschäftigten durch gezielte Weiterbildung auf die veränderten Anforderungen vorzubereiten. Die Verantwortung __(6)__ liegt sowohl bei den Unternehmen als auch bei der Politik. __(7)__ der Herausforderungen bietet die KI-Revolution auch Chancen für mehr Kreativität und weniger monotone Arbeit. Es __(8)__ kaum zu bestreiten sein, dass die Arbeitswelt von morgen grundlegend anders aussehen wird.", "gaps": [{"options": ["gewinnt", "nimmt", "steigt", "wächst"]}, {"options": ["vor", "über", "um", "gegen"]}, {"options": ["von", "aus", "mit", "bei"]}, {"options": ["Andererseits", "Allerdings", "Obwohl", "Dennoch"]}, {"options": ["inwieweit", "insofern", "infolge", "indessen"]}, {"options": ["dafür", "hierfür", "wofür", "darum"]}, {"options": ["Trotz", "Wegen", "Mangels", "Infolge"]}, {"options": ["dürfte", "sollte", "müsste", "könnte"]}]}', '{"answers": ["gewinnt", "vor", "von", "Andererseits", "inwieweit", "dafür", "Trotz", "dürfte"]}', 'Schwerpunkte: an Bedeutung gewinnen, sich fürchten vor, von der Hand weisen, Konzessivpräposition (trotz + Gen.), Konjunktiv II (dürfte).', 'Focus: an Bedeutung gewinnen, sich fürchten vor, von der Hand weisen, concessive preposition (trotz + gen.), subjunctive II (dürfte).', 3, 503);

INSERT INTO exercises (area, level, topic, exercise_type, exam_format, title_de, title_en, instructions_de, instructions_en, content, solution, explanation_de, explanation_en, difficulty, sort_order)
VALUES ('sprachbausteine', 'c1', 'sprachbausteine', 'sprachbausteine', 'telc', 'Bildung und Chancengleichheit', 'Education and Equal Opportunities', 'Lesen Sie den Text und wählen Sie für jede Lücke die richtige Lösung.', 'Read the text and choose the correct option for each gap.', '{"text": "Bildung gilt als Schlüssel __(1)__ gesellschaftlichem Aufstieg. __(2)__ ist der Bildungserfolg in Deutschland nach wie vor stark vom Elternhaus abhängig. Kinder aus bildungsfernen Familien haben es __(3)__ schwerer, einen höheren Schulabschluss zu erlangen. Zahlreiche Studien belegen, dass der Zusammenhang __(4)__ sozialer Herkunft und Bildungschancen in kaum einem anderen europäischen Land so ausgeprägt ist. Die Politik hat dieses Problem zwar __(5)__ Kenntnis genommen, doch die bisherigen Maßnahmen __(6)__ als unzureichend. Es __(7)__ einer grundlegenden Reform des Bildungssystems, um echte Chancengleichheit herzustellen. Dabei sollte nicht nur in Schulen investiert werden, __(8)__ auch in frühkindliche Bildungsangebote.", "gaps": [{"options": ["zu", "für", "auf", "bei"]}, {"options": ["Dennoch", "Deshalb", "Dadurch", "Demnach"]}, {"options": ["deutlich", "erheblich", "wesentlich", "besonders"]}, {"options": ["zwischen", "von", "mit", "unter"]}, {"options": ["zur", "in", "unter", "auf"]}, {"options": ["gelten", "erweisen", "erscheinen", "erklären"]}, {"options": ["bedarf", "benötigt", "braucht", "erfordert"]}, {"options": ["sondern", "aber", "jedoch", "allerdings"]}]}', '{"answers": ["zu", "Dennoch", "deutlich", "zwischen", "zur", "gelten", "bedarf", "sondern"]}', 'Schwerpunkte: Schlüssel zu, Zusammenhang zwischen, zur Kenntnis nehmen, es bedarf + Gen., nicht nur...sondern auch.', 'Focus: Schlüssel zu, Zusammenhang zwischen, zur Kenntnis nehmen, es bedarf + gen., nicht nur...sondern auch.', 3, 504);

INSERT INTO exercises (area, level, topic, exercise_type, exam_format, title_de, title_en, instructions_de, instructions_en, content, solution, explanation_de, explanation_en, difficulty, sort_order)
VALUES ('sprachbausteine', 'c1', 'sprachbausteine', 'sprachbausteine', 'telc', 'Migration und Integration', 'Migration and Integration', 'Lesen Sie den Text und wählen Sie für jede Lücke die richtige Lösung.', 'Read the text and choose the correct option for each gap.', '{"text": "Die Integration von Zuwanderern stellt moderne Gesellschaften __(1)__ große Herausforderungen. Sprache spielt dabei eine zentrale __(2)__, denn sie ist Voraussetzung für die Teilhabe am gesellschaftlichen Leben. __(3)__ sind Integrationskurse allein nicht ausreichend — es bedarf auch der Bereitschaft der Aufnahmegesellschaft. Vorurteile und Diskriminierung __(4)__ nach wie vor den Integrationsprozess. __(5)__ der vielfältigen Bemühungen gelingt es nicht allen Zugewanderten, auf dem Arbeitsmarkt Fuß zu __(6)__. Experten plädieren __(7)__ eine differenziertere Betrachtung: Weder pauschale Ablehnung noch blinder Optimismus werden den komplexen Realitäten gerecht. Entscheidend ist, dass Integration als Prozess __(8)__ wird, der Zeit und gegenseitigen Respekt erfordert.", "gaps": [{"options": ["vor", "an", "mit", "gegenüber"]}, {"options": ["Rolle", "Aufgabe", "Funktion", "Bedeutung"]}, {"options": ["Allerdings", "Folglich", "Insofern", "Inzwischen"]}, {"options": ["erschweren", "verhindern", "behindern", "belasten"]}, {"options": ["Trotz", "Wegen", "Dank", "Aufgrund"]}, {"options": ["fassen", "greifen", "setzen", "stellen"]}, {"options": ["für", "auf", "zu", "über"]}, {"options": ["verstanden", "betrachtet", "angesehen", "gesehen"]}]}', '{"answers": ["vor", "Rolle", "Allerdings", "erschweren", "Trotz", "fassen", "für", "verstanden"]}', 'Schwerpunkte: vor Herausforderungen stellen, eine Rolle spielen, Fuß fassen, plädieren für, als...verstanden werden.', 'Focus: vor Herausforderungen stellen, eine Rolle spielen, Fuß fassen, plädieren für, als...verstanden werden.', 3, 505);
